//! Host-managed non-secret preferences shared with team execution gates.
use crate::{Shared,Res,locked};
use serde::{Serialize,Deserialize};use serde_json::{Value,json};use std::{collections::BTreeMap,path::{Path,PathBuf},sync::Mutex,io::Write};
#[derive(Clone,Serialize,Deserialize,Debug)]#[serde(rename_all="camelCase",deny_unknown_fields)]
pub(crate) struct Settings{pub analysis_count:u64,pub generation_count:u64,pub cost_cny:f64,pub filter_count:u64,pub image_model:String,pub quotas:BTreeMap<String,Option<u64>>}
impl Default for Settings{fn default()->Self{Self{analysis_count:20,generation_count:4,cost_cny:2.,filter_count:50,image_model:crate::new_product::IMAGE.into(),quotas:BTreeMap::new()}}}
static WRITES:Mutex<()>=Mutex::new(());
fn directory(s:&Shared)->Res<PathBuf>{Ok(crate::team::settings_root().unwrap_or(locked(s)?.root.clone()))}
fn read_at(root:&Path)->Res<Settings>{match std::fs::read(root.join("frontend-settings.json")){Ok(bytes)=>serde_json::from_slice(&bytes).map_err(|_|"SETTINGS_CORRUPT".into()),Err(e)if e.kind()==std::io::ErrorKind::NotFound=>Ok(Settings::default()),Err(_)=>Err("SETTINGS_UNAVAILABLE".into())}}
pub(crate) fn read(s:&Shared)->Res<Settings>{read_at(&directory(s)?)}
pub(crate) fn atomic_bytes(root:&Path,name:&str,bytes:&[u8])->Res<()>{let mut file=tempfile::NamedTempFile::new_in(root).map_err(|_|"SETTINGS_UNAVAILABLE")?;file.write_all(bytes).map_err(|_|"SETTINGS_SAVE_FAILED")?;file.as_file().sync_all().map_err(|_|"SETTINGS_SAVE_FAILED")?;crate::frontend_ops::persist_temp(file,root.join(name))}
fn validate(settings:&Settings,catalog:&crate::models::Catalog)->Res<()>{if !(1..=5000).contains(&settings.analysis_count)||!(1..=5000).contains(&settings.generation_count)||!(1..=5000).contains(&settings.filter_count)||!settings.cost_cny.is_finite()||settings.cost_cny<=0.||settings.cost_cny>1_000_000.||!catalog.models.iter().any(|m|m.id==settings.image_model)||settings.quotas.iter().any(|(id,limit)|id!="host"&&uuid::Uuid::parse_str(id).is_err()||limit.is_some_and(|n|n==0||n>10_000_000)){return Err("INVALID_SETTINGS".into())}Ok(())}
pub(crate) fn patch(s:&Shared,patch:&Value)->Res<Settings>{let _guard=WRITES.lock().map_err(|_|"SETTINGS_BUSY")?;let root=directory(s)?;let mut current=serde_json::to_value(read_at(&root)?).map_err(|_|"SETTINGS_UNAVAILABLE")?;let fields=patch.as_object().filter(|p|!p.is_empty()).ok_or("INVALID_SETTINGS")?;for(key,value)in fields{if !current.as_object().unwrap().contains_key(key){return Err("INVALID_SETTINGS".into())}if key=="quotas"{let quotas=value.as_object().ok_or("INVALID_SETTINGS")?;for(id,limit)in quotas{current["quotas"][id]=limit.clone();}}else{current[key]=value.clone();}}let settings:Settings=serde_json::from_value(current).map_err(|_|"INVALID_SETTINGS")?;validate(&settings,&crate::models::load(&locked(s)?.root).0)?;atomic_bytes(&root,"frontend-settings.json",&serde_json::to_vec(&settings).map_err(|_|"SETTINGS_SAVE_FAILED")?)?;Ok(settings)}
pub(crate) fn account_key(s:&Shared)->Res<String>{let root=locked(s)?.root.clone();Ok(if root.parent().and_then(|p|p.file_name()).is_some_and(|n|n=="workspaces"){root.file_name().unwrap().to_string_lossy().into()}else{"host".into()})}
pub(crate) fn used(s:&Shared)->Res<u64>{Ok(crate::frontend_api::list(s)?.iter().map(|task|task["quotaUnits"].as_u64().unwrap_or_else(||task["done"].as_u64().unwrap_or(0))).sum())}
pub(crate) fn quota(s:&Shared)->Res<Option<Value>>{let settings=read(s)?;let key=account_key(s)?;let Some(limit)=settings.quotas.get(&key).copied().flatten()else{return Ok(None)};Ok(Some(json!({"used":used(s)?,"limit":limit,"unit":"images"})))}
pub(crate) fn near_quota(s:&Shared,count:usize)->Res<bool>{Ok(quota(s)?.is_some_and(|q|{let limit=q["limit"].as_u64().unwrap();q["used"].as_u64().unwrap().saturating_add(count as u64) as f64>limit as f64*0.95}))}
#[cfg(test)]mod tests{use super::*;
 fn setup()->(tempfile::TempDir,Shared){let t=tempfile::tempdir().unwrap();let store=crate::core::Store::open(t.path().into(),"test").unwrap();let s=std::sync::Arc::new(crate::AppState{store:Mutex::new(store),cancel:std::sync::atomic::AtomicBool::new(false),local_job:Mutex::new(()),preview_epoch:std::sync::atomic::AtomicU64::new(0)});(t,s)}
 #[test]fn patches_merge_fields_persist_and_reject_unknown_or_invalid_without_writing(){let(t,s)=setup();assert_eq!(read(&s).unwrap().analysis_count,20);patch(&s,&json!({"generationCount":7,"costCny":3.5})).unwrap();patch(&s,&json!({"filterCount":80})).unwrap();let saved=read(&s).unwrap();assert_eq!(saved.generation_count,7);assert_eq!(saved.cost_cny,3.5);assert_eq!(saved.filter_count,80);let before=std::fs::read(t.path().join("frontend-settings.json")).unwrap();for invalid in [json!({"costCny":0}),json!({"imageModel":"unknown"}),json!({"secret":"never"}),json!({"quotas":{"host":0}})]{assert!(patch(&s,&invalid).is_err())}assert_eq!(std::fs::read(t.path().join("frontend-settings.json")).unwrap(),before);}
 #[test]fn configured_quota_uses_real_persisted_done_counts_and_unlimited_stays_unknown(){let(t,s)=setup();assert!(quota(&s).unwrap().is_none());patch(&s,&json!({"quotas":{"host":10}})).unwrap();let dir=t.path().join("new-product-jobs");std::fs::create_dir(&dir).unwrap();std::fs::write(dir.join("fixture.json"),json!({"id":"one","projectId":"p","status":"done","tasks":[{"state":"done"},{"state":"failed"},{"state":"done"}]}).to_string()).unwrap();assert_eq!(quota(&s).unwrap().unwrap()["used"],2);assert!(!near_quota(&s,7).unwrap());assert!(near_quota(&s,8).unwrap());patch(&s,&json!({"quotas":{"host":null}})).unwrap();assert!(quota(&s).unwrap().is_none());}
}
